#include "amity/consortium/relay.hpp"
#include <algorithm>
namespace amity::consortium {
namespace {
bool same_scope(const LinkScope&a,const LinkScope&b){return a.link_id==b.link_id&&a.consortium_id==b.consortium_id&&a.local_id==b.local_id&&a.peer_id==b.peer_id&&a.coordinator_id==b.coordinator_id&&a.local_boot_id==b.local_boot_id&&a.peer_boot_id==b.peer_boot_id&&a.epoch==b.epoch&&a.config_revision==b.config_revision;}
bool text(const Json *v,std::initializer_list<const char*> choices){return v&&v->type==Json::Type::string&&std::any_of(choices.begin(),choices.end(),[&](const auto *c){return v->string==c;});}
std::string hex(std::string_view value){std::string result;for(unsigned char c:value){result+="0123456789abcdef"[c>>4];result+="0123456789abcdef"[c&15];}return result;}
bool unhex(const Json *value,std::string &out){if(!value||value->type!=Json::Type::string||value->string.empty()||value->string.size()>4096||value->string.size()%2)return false;out.clear();auto digit=[](char c){return c>='0'&&c<='9'?c-'0':c>='a'&&c<='f'?c-'a'+10:-1;};for(size_t n=0;n<value->string.size();n+=2){int a=digit(value->string[n]),b=digit(value->string[n+1]);if(a<0||b<0)return false;out+=char(a*16+b);}return true;}
bool ids(const Json &v){model::MessageId reservation;model::JoinId join;return id(v.get("reservation_id"),reservation)&&id(v.get("join_id"),join);}
}
bool is_relay_kind(Kind kind){return kind==Kind::relay_reserve||kind==Kind::relay_record||kind==Kind::relay_close||kind==Kind::relay_result;}
Error parse_relay_fragment(const Json &v,RelayFragment &out){RelayFragment f;uint64_t total=0,offset=0;if(!id(v.get("reservation_id"),f.reservation_id)||!id(v.get("join_id"),f.join_id)||!id(v.get("request_id"),f.request_id)||!decimal(v.get("record_sequence"),f.sequence)||!f.sequence||!json_uint(v.get("record_length"),total,1,4096)||!json_uint(v.get("offset"),offset,0,4095)||!text(v.get("endpoint"),{"session","encrypted"})||!unhex(v.get("data_hex"),f.data)||offset+f.data.size()>total)return Error::invalid_message;f.total=total;f.offset=offset;f.encrypted=text(v.get("endpoint"),{"encrypted"});out=std::move(f);return Error::none;}
bool validate_relay_payload(Kind kind,const Json &v){
    if(!ids(v))return false;
    if(kind==Kind::relay_reserve){model::OctopusId candidate;uint64_t duration=0;return closed(v,{"reservation_id","join_id","candidate_id","validity_ms"})&&id(v.get("candidate_id"),candidate)&&json_uint(v.get("validity_ms"),duration,1,180000);}
    if(kind==Kind::relay_close)return closed(v,{"reservation_id","join_id","reason"})&&text(v.get("reason"),{"completed","cancelled","expired","disconnected","revoked","coordinator_changed","failed"});
    if(kind==Kind::relay_record){RelayFragment f;return closed(v,{"reservation_id","join_id","request_id","record_sequence","endpoint","record_length","offset","data_hex"})&&parse_relay_fragment(v,f)==Error::none;}
    if(kind!=Kind::relay_result||!text(v.get("error"),{"","RADIO_BUSY","NO_CANDIDATE","EXPIRED","CONFLICT","INTERNAL_ERROR"}))return false;
    if(text(v.get("phase"),{"record"})&&text(v.get("result"),{"data"})){RelayFragment f;return closed(v,{"reservation_id","join_id","phase","result","error","request_id","record_sequence","endpoint","record_length","offset","data_hex"})&&text(v.get("error"),{""})&&parse_relay_fragment(v,f)==Error::none;}
    if(text(v.get("phase"),{"record"})){model::MessageId request;return closed(v,{"reservation_id","join_id","phase","result","error","request_id"})&&text(v.get("result"),{"failed"})&&id(v.get("request_id"),request);}
    return closed(v,{"reservation_id","join_id","phase","result","error"})&&((text(v.get("phase"),{"reserve"})&&text(v.get("result"),{"ready","busy","failed"}))||(text(v.get("phase"),{"close"})&&text(v.get("result"),{"closed"})));
}
std::string relay_fragment_json(const RelayFragment &f,bool response){return "{\"reservation_id\":\""+f.reservation_id.str()+"\",\"join_id\":\""+f.join_id.str()+"\",\"request_id\":\""+f.request_id.str()+"\",\"record_sequence\":\""+std::to_string(f.sequence)+"\",\"endpoint\":\""+(f.encrypted?"encrypted":"session")+"\",\"record_length\":"+std::to_string(f.total)+",\"offset\":"+std::to_string(f.offset)+",\"data_hex\":\""+hex(f.data)+"\""+(response?",\"phase\":\"record\",\"result\":\"data\",\"error\":\"\"":"")+"}";}
Error RelayBuffer::append(const RelayFragment &f){if(!f.reservation_id||!f.join_id||!f.request_id||!f.sequence||!f.total||f.total>4096||f.data.empty()||f.data.size()>2048||f.offset+f.data.size()>f.total)return Error::invalid_message;if(!initialized_){if(f.offset)return Error::invalid_message;fragment_=f;fragment_.data.clear();initialized_=true;}if(f.reservation_id!=fragment_.reservation_id||f.join_id!=fragment_.join_id||f.request_id!=fragment_.request_id||f.sequence!=fragment_.sequence||f.total!=fragment_.total||f.encrypted!=fragment_.encrypted)return Error::transaction_conflict;if(f.offset<bytes_.size()){if(f.offset+f.data.size()>bytes_.size()||bytes_.compare(f.offset,f.data.size(),f.data)!=0)return Error::transaction_conflict;return Error::duplicate;}if(f.offset!=bytes_.size())return Error::invalid_message;bytes_+=f.data;return Error::none;}
Error OpaqueRelay::reserve(const LinkScope &s,model::MessageId reservation,model::JoinId join,model::OctopusId candidate,uint32_t duration,uint64_t now){if(!reservation||!join||!candidate||!s.link_id||!s.local_boot_id||!s.peer_boot_id||!duration||duration>180000||now>UINT64_MAX-duration)return Error::invalid_message;if(deadline_&&now<deadline_)return reservation==reservation_&&join==join_&&candidate==candidate_&&same_scope(s,scope_)?Error::duplicate:Error::queue_full;cancel();scope_=s;reservation_=reservation;join_=join;candidate_=candidate;issued_=now;deadline_=now+duration;return Error::none;}
bool OpaqueRelay::live(const LinkScope&s,uint64_t now)const{return deadline_&&now>=issued_&&now<deadline_&&same_scope(s,scope_);}
Error OpaqueRelay::append(const LinkScope&s,const RelayFragment&f,uint64_t now){if(!live(s,now))return Error::lease_expired;if(f.reservation_id!=reservation_||f.join_id!=join_)return Error::transaction_conflict;if(f.sequence<highwater_||(!cached_&&f.sequence<=highwater_))return Error::duplicate;if(cached_&&f.sequence==highwater_){if(f.request_id!=input_.fragment().request_id)return Error::transaction_conflict;return input_.append(f);}if(f.sequence!=highwater_+1)return Error::invalid_message;if(cached_){input_.reset();response_.clear();cached_=false;forwarded_=false;}return input_.append(f);}
std::optional<RelayFragment> OpaqueRelay::take_request(){if(!input_.complete()||forwarded_||cached_)return {};forwarded_=true;auto request=input_.fragment();request.data=input_.bytes();return request;}
bool OpaqueRelay::finish(const LinkScope&s,model::MessageId request,uint64_t sequence,std::string reply,uint64_t now){if(!live(s,now)||!forwarded_||cached_||request!=input_.fragment().request_id||sequence!=input_.fragment().sequence||reply.empty()||reply.size()>4096)return false;response_=std::move(reply);highwater_=sequence;cached_=true;return true;}
void OpaqueRelay::cancel(){issued_=deadline_=highwater_=0;reservation_={};join_={};candidate_={};forwarded_=cached_=false;input_.reset();response_.clear();}
}
